struct Link { std::string rel, href, method; };
std::vector<Link> links_for(const Order& o) {            // producer
  return {{"customer", "/customers/" + o.customer_id, "GET"},
          {"payment",  "/payments/"  + o.payment_id,  "GET"}};
}
void consume(const std::vector<Link>& _links) {          // consumer
  auto it = std::find_if(begin(_links), end(_links),
                         [](const Link& l) { return l.rel == "payment"; });
  if (it != end(_links)) follow(it->method, it->href);   // e.g. http_client
}
